const user = {
  name: 'Alice',
  greetRegular() {
    setTimeout(function() {
      console.log(`Regular: ${this.name}`);
    }, 100);
  },
  greetArrow() {
    setTimeout(() => {
      console.log(`Arrow: ${this.name}`);
    }, 100);
  }
};

user.greetRegular();
user.greetArrow();

